```c
/*  quadrant.c
 *
 *  Checks if two points belong to the same Cartesian quadrant.
 *  Point1 = { 1, -2 }
 *  Point2 = { -3, 4 }
 *
 *  Compile:
 *      gcc -std=c11 -Wall -Wextra -o quadrant quadrant.c
 *
 *  Run:
 *      ./quadrant
 */

#include <stdio.h>

/* ---- Data structure ----------------------------------------------------- */
typedef struct {
    int x;   /* x‑coordinate */
    int y;   /* y‑coordinate */
} Point;

/* ---- Helper function --------------------------------------------------- */
/* Return 1,2,3,4 for the usual quadrants or 0 if the point lies on an axis. */
int quadrant(const Point *p)
{
    if (p->x == 0 || p->y == 0)   /* on an axis */
        return 0;

    if (p->x > 0 && p->y > 0)     return 1;
    if (p->x < 0 && p->y > 0)     return 2;
    if (p->x < 0 && p->y < 0)     return 3;
    return 4;                     /* x > 0 && y < 0 */
}

/* ---- Main program ------------------------------------------------------- */
int main(void)
{
    /* The two points supplied by the user/problem statement */
    Point p1 = { 1, -2 };
    Point p2 = { -3, 4 };

    int q1 = quadrant(&p1);
    int q2 = quadrant(&p2);

    /* Pretty print the points */
    printf("Point 1: (%d, %d) -> ", p1.x, p1.y);
    if (q1 == 0) printf("on an axis\n");
    else         printf("Quadrant %d\n", q1);

    printf("Point 2: (%d, %d) -> ", p2.x, p2.y);
    if (q2 == 0) printf("on an axis\n");
    else         printf("Quadrant %d\n", q2);

    /* Check same‑quadrant */
    if (q1 == 0 || q2 == 0) {
        printf("At least one point lies on an axis – no quadrant comparison.\n");
    } else if (q1 == q2) {
        printf("Both points belong to the same quadrant (%d).\n", q1);
    } else {
        printf("Points belong to different quadrants (Q%d vs Q%d).\n", q1, q2);
    }

    return 0;
}
```

