### Complete C Program

```c
/*  check_quadrant.c
 *
 *  Determines whether two points are in the same Cartesian quadrant.
 *
 *  Author:  <your name>
 *  Date:    2026‑10‑27
 */

#include <stdio.h>

/* Enumeration for readability */
typedef enum {
    QUAD_I = 1,
    QUAD_II,
    QUAD_III,
    QUAD_IV,
    AXIS   /* point lies on the x‑ or y‑axis */
} Quadrant;

/*--------------------------------------------------------------
 *  Returns the quadrant of the point (x, y).
 *  If the point lies on an axis, returns AXIS.
 *--------------------------------------------------------------*/
Quadrant getQuadrant(int x, int y)
{
    if (x == 0 || y == 0)          /* on an axis */
        return AXIS;

    if (x > 0 && y > 0)  return QUAD_I;
    if (x < 0 && y > 0)  return QUAD_II;
    if (x < 0 && y < 0)  return QUAD_III;
    /* remaining case: x > 0 && y < 0 */
    return QUAD_IV;
}

/*--------------------------------------------------------------
 *  Returns a printable string for a quadrant enum value.
 *--------------------------------------------------------------*/
const char *quadrantName(Quadrant q)
{
    switch (q) {
        case QUAD_I:   return "I";
        case QUAD_II:  return "II";
        case QUAD_III: return "III";
        case QUAD_IV:  return "IV";
        case AXIS:     return "on an axis";
        default:       return "unknown";
    }
}

/*--------------------------------------------------------------
 *  Main program
 *--------------------------------------------------------------*/
int main(void)
{
    /* ---- Input points ------------------------------------------------ */
    /* You can replace these literals with scanf() calls if you want
       interactive input. */
    int p1x =  1, p1y = -2;   /* Point1 = {1, -2} */
    int p2x = -3, p2y =  4;   /* Point2 = {-3, 4} */

    /* ---- Determine quadrants ------------------------------------------ */
    Quadrant q1 = getQuadrant(p1x, p1y);
    Quadrant q2 = getQuadrant(p2x, p2y);

    /* ---- Output -------------------------------------------------------- */
    printf("Point1 = {%d, %d}  →  Quadrant %s\n", p1x, p1y, quadrantName(q1));
    printf("Point2 = {%d, %d}  →  Quadrant %s\n", p2x, p2y, quadrantName(q2));

    if (q1 == AXIS || q2 == AXIS) {
        printf("At least one point lies on an axis, so they cannot be in the same quadrant.\n");
    } else if (q1 == q2) {
        printf("Both points are in the same quadrant.\n");
    } else {
        printf("The points are in different quadrants.\n");
    }

    return 0;
}
```

