#include <stdio.h>

// Function to determine the quadrant of a point
// Returns:
//   1 for Quadrant I (x > 0, y > 0)
//  -1 for Quadrant II (x < 0, y > 0)
//   2 for Quadrant III (x < 0, y < 0)
//  -2 for Quadrant IV (x > 0, y < 0)
//   0 if the point is on an axis or at the origin

int getQuadrant(int x, int y) {
    if (x > 0 && y > 0) {
        return 1;
    } else if (x < 0 && y > 0) {
        return -1;
    } else if (x < 0 && y < 0) {
        return 2;
    } else if (x > 0 && y < 0) {
        return -2;
    } else {
        return 0; // On an axis or at the origin
    }
}

// Structure to represent a point
typedef struct {
    int x;
    int y;
} Point;

int main() {
    Point point1 = {1, -2};
    Point point2 = {-3, 4};

    int quadrant1 = getQuadrant(point1.x, point1.y);
    int quadrant2 = getQuadrant(point2.x, point2.y);

    if (quadrant1 == 0 || quadrant2 == 0) {
        printf("One or both points are on an axis or at the origin, so they do not belong to a quadrant.\n");
    } else if (quadrant1 == quadrant2) {
        printf("Both points belong to the same quadrant.\n");
    } else {
        printf("The points belong to different quadrants.\n");
    }

    return 0;
}
